if ((pt_input.enable != 0 && pt_input.enable != 1) ||
    pt_input.field_body_t == NULL ||
    pt_input.measured_torque_nm == NULL ||
    !adcs_is_finite_vec3(pt_input.field_body_t) ||
    !adcs_is_finite_vec3(pt_input.measured_torque_nm) ||
    !isfinite(pt_config.test_dipole_a_m2) ||
    pt_config.test_dipole_a_m2 <= 0.0 ||
    !isfinite(pt_config.min_fraction) ||
    pt_config.min_fraction <= 0.0 ||
    pt_config.min_fraction > 1.0 ||
    pt_config.confirm_samples < 1 ||
    pt_config.confirm_samples > 20 ||
    pt_config.max_samples_per_phase < 1 ||
    pt_config.max_samples_per_phase > 200) {

    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

adcs_vec3_t unit_axis;
if (adcs_vec3_normalize(&pt_config.test_axis_body, ADCS_EPS_NORM, &unit_axis) != ADCS_OK) {
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

double b_norm = adcs_vec3_norm(pt_input.field_body_t);
if (b_norm <= ADCS_EPS_NORM) {
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

double m_norm = adcs_vec3_norm(pt_input.measured_torque_nm);
if (m_norm <= ADCS_EPS_NORM) {
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 2. Handle Disable
if (pt_input.enable == 0) {
    pt_state.mode = PT_IDLE;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;
    pt_output.mode = PT_IDLE;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 3. Locked States
if (pt_state.mode == PT_PASS || pt_state.mode == PT_FAULT) {
    pt_output.mode = pt_state.mode;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 4. Determine Dipole Direction
double sign = (pt_state.mode == PT_IDLE) ? 1.0 : -1.0;
adcs_vec3_t dipole = adcs_vec3_scale(&unit_axis, sign * pt_config.test_dipole_a_m2);

// 5. Expected Torque
adcs_vec3_t expected_torque = adcs_vec3_cross(&dipole, pt_input.field_body_t);
double expected_norm_sq = adcs_vec3_dot(&expected_torque, &expected_torque);

if (sqrt(expected_norm_sq) <= ADCS_EPS_NORM) {
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;
    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;
    return;
}

// 6. Projection and Alignment
double projection = adcs_vec3_dot(pt_input.measured_torque_nm, &expected_torque);
double alignment_cosine = projection / (m_norm * sqrt(expected_norm_sq));

// 7. State Transition
int adequate = (projection >= pt_config.min_fraction * expected_norm_sq);

if (adequate) {
    pt_state.confirm_count++;
    pt_state.sample_count = 0;

    if (pt_state.confirm_count >= pt_config.confirm_samples) {
        if (pt_state.mode == PT_IDLE) {
            pt_state.mode = PT_NEGATIVE;
        } else if (pt_state.mode == PT_NEGATIVE) {
            pt_state.mode = PT_PASS;
        }
        pt_state.confirm_count = 0;
    }
} else {
    pt_state.confirm_count = 0;
    pt_state.sample_count++;

    if (pt_state.sample_count >= pt_config.max_samples_per_phase) {
        pt_state.mode = PT_FAULT;
    }
}

// 8. Output Assignment
pt_output.mode = pt_state.mode;

if (pt_state.mode == PT_PASS || pt_state.mode == PT_FAULT) {
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
} else if (pt_state.mode == PT_IDLE) {
    pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, pt_config.test_dipole_a_m2);
} else if (pt_state.mode == PT_NEGATIVE) {
    pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, -pt_config.test_dipole_a_m2);
}

pt_output.expected_torque_nm = expected_torque;
pt_output.projection_nm2 = projection;
pt_output.alignment_cosine = alignment_cosine;

